// S22 and S29 acceptance (TICK-754): helpers for folders S22 and S29. Their
// requests wait for an index removal or a schema backfill, longer than an
// access token lives (300 s), so every call signs in again when its token is
// close to expiry. Generated by docs/acceptance/guide/build/kits_s22_s29.py;
// edit it there.
const crypto = require('crypto');
const USERS = {
  admin_a_token: ['admin_a_username', 'admin_a_password', 'nava-web'],
  alice_token: ['alice_username', 'alice_password', 'nava-web'],
  admin_b_token: ['admin_b_username', 'admin_b_password', 'nava-web'],
  operator_token: ['operator_username', 'operator_password', 'nava-operator-cli'],
};

module.exports = (N, bru) => {
  const T = {
    // The token in v, signed in again when it expires within 90 s.
    async fresh(v) {
      const t = bru.getVar(v);
      if (t && N.jwt(t).exp * 1000 - Date.now() > 90000) return t;
      const [u, p, client] = USERS[v];
      const r = await N.token(N.v(u), N.v(p), { client, timeout: 15000 });
      if (r.status !== 200) throw new Error(`sign-in again for ${v}: HTTP ${r.status}`);
      bru.setVar(v, r.data.access_token);
      return r.data.access_token;
    },
    // base: '{{core_url}}' (tenant API) or '{{onboard_url}}' (operator API).
    async call(v, method, path, data, headers = {}, base = '{{core_url}}') {
      const h = { Authorization: 'Bearer ' + (await T.fresh(v)), ...headers };
      if (data !== undefined && !h['Content-Type']) h['Content-Type'] = 'application/json';
      const t0 = Date.now();
      const r = await N.send({ url: N.url(base + path), method, headers: h, data, timeout: 30000 });
      return { status: r.status, data: r.data, ms: Date.now() - t0 };
    },
    type(v, key) { return T.call(v, 'GET', '/api/v1/entity-types/' + key); },
    publish(v, key, idem, definition) {
      return T.call(v, 'POST', '/api/v1/entity-types/' + key + '/versions', { definition }, { 'Idempotency-Key': idem });
    },
    list(v, key, query) { return T.call(v, 'GET', '/api/v1/records/' + key + '?' + query); },
    read(v, key, id) { return T.call(v, 'GET', '/api/v1/records/' + key + '/' + id); },
    history(v, key, id) { return T.call(v, 'GET', '/api/v1/records/' + key + '/' + id + '/history'); },
    create(v, key, idem, data) {
      return T.call(v, 'POST', '/api/v1/records/' + key, { data }, { 'Idempotency-Key': idem });
    },
    patch(v, key, idem, id, version, data) {
      return T.call(v, 'PATCH', '/api/v1/records/' + key + '/' + id, { data },
        { 'Idempotency-Key': idem, 'Content-Type': 'application/merge-patch+json', 'If-Match': `W/"${version}"` });
    },
    // The total contract of a list body (ADR-006-A2 A2-1): null when it holds.
    contract(b) {
      if (!b || typeof b !== 'object') return 'no body';
      const s = b.total_state;
      if (!['exact', 'capped', 'unknown'].includes(s)) return `total_state ${JSON.stringify(s)}`;
      if (!('total' in b)) return 'no total';
      if (s === 'unknown' && b.total !== null) return `unknown with total ${JSON.stringify(b.total)}`;
      if (s === 'exact' && !(Number.isInteger(b.total) && b.total >= 0 && b.total <= 1000)) return `exact with total ${JSON.stringify(b.total)}`;
      if (s === 'capped' && b.total !== 1000) return `capped with total ${JSON.stringify(b.total)}`;
      if ((b.total_capped === true) !== (s === 'capped')) return `total_capped ${JSON.stringify(b.total_capped)} with ${s}`;
      return null;
    },
    // What a count of n matches must answer: exact n up to 1,000, capped at
    // 1,000 past it, or unknown (null) when the count ran out of budget.
    totalOk(b, n) {
      if (T.contract(b)) return false;
      if (b.total_state === 'unknown') return n > 0;
      return b.total === Math.min(n, 1000) && b.total_state === (n > 1000 ? 'capped' : 'exact');
    },
    // A result over 1,000 matches (ADR-006-A2; Technical Lead ruling on S29
    // criterion 1, TICK-754, 2026-11-26): null when the page answers capped
    // with total 1,000 and total_capped true, or unknown with total a JSON
    // null (the key present, not 0). exact, or a total under 1,000, fails.
    bigTotal(b) {
      if (!b || typeof b !== 'object') return 'no body';
      const has = b.has_total !== undefined ? b.has_total : ('total' in b);
      if (b.total_state === 'capped') return b.total === 1000 && b.total_capped === true ? null : `capped with total ${JSON.stringify(b.total)}, total_capped ${JSON.stringify(b.total_capped)}`;
      if (b.total_state === 'unknown') return has && b.total === null ? null : `unknown with total ${has ? JSON.stringify(b.total) : 'missing'}`;
      return `total_state ${JSON.stringify(b.total_state)}, total ${has ? JSON.stringify(b.total) : 'missing'}: want capped 1,000 or unknown null`;
    },
    // Every record a filter lists, page by page (limit 200, next_cursor), with
    // each page's total fields (has_total: the key was there, even if null).
    async all(v, key, query) {
      const items = [], broken = [], totals = [];
      let cursor = null, first = null, pages = 0;
      do {
        const r = await T.list(v, key, query + '&limit=200' + (cursor ? '&cursor=' + encodeURIComponent(cursor) : ''));
        if (r.status !== 200) return { status: r.status, body: r.data, items, ids: items.map(i => i.id), first, pages, broken, totals };
        if (!first) first = r.data;
        const bad = T.contract(r.data);
        if (bad) broken.push(`page ${pages + 1}: ${bad}`);
        totals.push({ total_state: r.data.total_state, total: r.data.total, has_total: 'total' in r.data, total_capped: r.data.total_capped });
        items.push(...r.data.items);
        cursor = r.data.next_cursor;
        pages++;
      } while (cursor);
      return { status: 200, items, ids: items.map(i => i.id), first, pages, broken, totals };
    },
    // The uuid Postgres gives md5(text)::uuid, as the kits' seed.sql ids are.
    md5uuid(s) {
      const h = crypto.createHash('md5').update(s).digest('hex');
      return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
    },
    md5: (ids) => crypto.createHash('md5').update([...ids].sort().join(',')).digest('hex'),
    // Calls step() every `every` ms until done(result) or `limit` ms pass;
    // returns every sample (the last one is the one that ended the loop).
    async until(step, done, { every = 3000, limit = 600000 } = {}) {
      const t0 = Date.now(), samples = [];
      for (;;) {
        const s = await step();
        s.at_s = Math.round((Date.now() - t0) / 1000);
        samples.push(s);
        if (done(s) || Date.now() - t0 > limit) return samples;
        await bru.sleep(every);
      }
    },
  };
  return T;
};
